        entry("skill:runtime:39858ce1c14896dd", "figma-generate-library", "3b6a1ebdf04c8704dde89524b6f6a0f97fec861d5b7011352a85f718a4df78eb", "从代码库在 Figma 中构建或更新专业设计系统，包括变量与令牌、组件库、变体、变量绑定、明暗主题和基础文档；即使只创建单个组件也应使用，并与讲解调用方法的 figma-use 同时加载。"),
        entry("skill:runtime:86cb495908447e73", "figma-implement-motion", "629fb9b12eb9c4f46852dbcae73f7238ff2df39c9f8381fe0d6e8b7db9b0577a", "把 Figma 中的动效与动画转化为生产级应用代码；用于实现 Figma 动效、为组件添加动画，或 get_design_context 返回动效数据并要求调用 get_motion_context 时。"),
        entry("skill:project:project-03d84e40d3db5911:a5b72480b4b251da", "figma-motion-delivery", "f0ef4cfafeefd985c37a0b3e4db09a38d970e773d9bd329bd448e9c500885394", "由 Motion Designer 在已批准的 After Effects、视频或 GIF 动画需要作为可播放媒体插入 Figma 时使用；涵盖 GIF/视频路线、H.264 MP4 准备、原生放置、VideoPaint 验证、海报帧与循环、回滚图层和播放 QA，也用于排查静态或错误导入的动效素材。"),
        entry("skill:project:project-03d84e40d3db5911:b5845ad0180f5e15", "figma-slide-intake", "f132259bc1fc29252244860bd67fc5f1584b2e74d8d5b907d3174d881a466d34", "在此作品集工作区完整读取 Figma 作品集演示、Slides 和屏幕集合的视觉内容；用于遍历所有页面、理解每张幻灯片或屏幕、捕获可见文字并同步到本地中文清单，避免实现层分析。"),
        entry("skill:project:project-03d84e40d3db5911:d18eb3eb4870f976", "figma-source-boards", "43a61dc8d6892d34607539a32377161e5bf4e7c5b5d221f3d348290aef4b7861", "在此作品集工作区把 Figma 源项目整理为目标汇总文件中的可编辑流程板；用于读取和分类屏幕、复制或重建可编辑节点、保留来源说明与市场徽标、比较市场版本，并准备 Wealth/PF UI 流程证据板。"),
        entry("skill:runtime:44eda7665f87b1db", "figma-swiftui", "752099a2895557abf92eb6caafe2d02501764b3e0e133a60d488288ca1262387", "处理 SwiftUI 与 Figma 的双向转换；只要涉及 Swift、SwiftUI、iOS、iPhone 或 iPad，无论 Figma → 代码还是代码 → Figma 都应使用。代码写回设计时与 figma-use 配合，并按方向加载对应参考文档。"),
        entry("skill:runtime:75f6094867116fcf", "figma-use", "c44c1a54da5bd5f9434dd046e196044f2cf5fa8f5d761ff070cd803841408003", "强制前置 Skill：每次调用 use_figma 前都必须加载，绝不能直接调用；适用于需在 Figma 文件上下文执行 JavaScript 的写入或特殊读取，如增删改节点、变量和令牌、组件变体、自动布局、填充、变量绑定或程序化结构检查。"),
        entry("skill:runtime:e9e600b6ca29eecf", "figma-use-figjam", "2e37f6c6b77c7d4a752b8ba551bec90a02e0ac06184c41b4e0fc38e0035285d3", "帮助 Agent 在 FigJam 场景中使用 Figma 的 use_figma MCP 工具，可与提供基础使用方法的 figma-use 同时使用。"),
        entry("skill:runtime:7adc4cc2b8f6d1ef", "figma-use-motion", "b6c5c0a99b464db09c9a6bcca931c7e366810d31dc3554dca0c014f6d23e99db", "为 use_figma 提供动效上下文，包括通过手动关键帧、动画样式、缓动和时间线时长来创建、编辑或检查 Figma 节点动画；涉及动效时与 figma-use 一同加载。"),
        entry("skill:runtime:8e1baebe588dcc9f", "figma-use-slides", "46d925bf8c6e561fc4f90f194c61a71a7fd604169445bb37b65871c616875a4d", "帮助 Agent 在 Figma Slides 场景中使用 use_figma MCP 工具，可与提供基础上下文的 figma-use 同时使用。"),
        entry("skill:global:agent-skills:25a1edbcab610d18", "find-skills", "aa775d8758bc72c7552fecb26e67d9dd07f4577757966622fc495fb4a6b20ffc", "当用户询问如何完成某事、寻找某项 Skill、确认是否存在可用 Skill，或希望扩展能力时，帮助发现并安装 Agent Skill。"),
        entry("skill:global:global-skills:3f04236490192df6", "flue", "7405ae245bf9d54b0cf39f08541e460004112e216a1fc2315fcc04fad7d0ba9a", "当 Codex 需要检查、安装、测试或运行 Flue 适配器，以通过本地脚本桥控制受支持的 Windows 与 macOS 桌面应用时使用。"),
        entry("skill:global:agent-skills:f8c5000c065bfd4d", "frontend-design", "05ef8f279aab306936f8bbf4f43abaa20aba8b45e56770417c02a8434f701cfb", "创建有辨识度、可用于生产且设计质量高的前端界面；用于构建网页组件、页面或应用，生成精致代码并避免千篇一律的 AI 风格。"),
        entry("skill:global:agent-skills:9b0d641d53faaca2", "git-essentials", "ba8294d12b68905a613c048aff55dbb52e0e7b5ecb906e2ddd1b712d833a415a", "提供版本控制、分支和协作所需的 Git 核心命令与工作流。"),
        entry("skill:project:project-b22d22ea4c868e2f:45c27c245fbe7069", "govern-project-architecture", "347f3023947358d395cf3278e765de5c9011302393814f019be2792e5fbd3a22", "治理 Codex Skin 的架构与多角色交付；供 System Architect 界定中大型变更、维护 ADR、分配文件职责、安排设计开发门槛、冻结接口、制作交接契约、协调工作树、解决跨角色冲突并更新持久进度。"),
        entry("skill:project:project-03d84e40d3db5911:b4e746e2995858f8", "graphic-volume-illustration", "295982db782c483ffadfc06291bb930f8fce3e9d1337d22dad01566d9001214e", "由 Illustration Designer 在已批准的实体物件构图需要保留体积、遮挡或透视，而直接生成平面图像显得泛化或扁平时使用；把浅立体结构母版转成以填色为主、透视受控的插画。不得用于系统图标、未解决的插画概念、照片级或最终 3D 交付、项目色板定义或位图转矢量。"),
        entry("skill:global:global-skills:87db48e1e88f6afc", "hallmark", "400b26dc5f71d8c304cc3b60cea064450750fe675193bbe3887ca955a3a8404c", "面向新页面、审计、重设计以及从 URL 或截图提取设计的反 AI 套路化 Skill；当用户要构建新应用或落地页、重设计、点名 Hallmark，或使用 audit、redesign、study 等指令时使用。"),
        entry("skill:project:project-03d84e40d3db5911:bd902cb65cb1ec36", "hr", "fe477cfbe395c6650932c019a1a6095b668cd64a2bfbeebe29a510164e1e979a", "在此作品集工作区模拟中国大陆设计岗位的 HR 或招聘者简历筛选，判断简历能否在不深入作品集或设计方法的情况下通过第一轮。"),
        entry("skill:global:agent-skills:12aac2c6b314206b", "icon-system", "0c9c12119dc46c38426d474a1bc581cd8cfab09d7b3074c20c496a462cfeee0b", "制定图标系统规范，涵盖网格、尺寸、命名、分类和实现指导。"),
        entry("skill:global:global-skills:ea7b964cf6c182c7", "illustrated-gradient-icons", "c8c67ab3958715dc75153ff70e4f00682ae3c09051198e03db46918d8caade3c", "由 Icon Designer 制作具有分层平面几何、克制渐变、受控重叠和细微纹理的服务图标、产品图标与象形图；每批都必须通过 Create Image 提案和明确批准后才能制作可编辑矢量。不得用于系统或工具字形、3D/玻璃图标、完整插画场景或仅交付最终位图。"),
        entry("skill:project:project-03d84e40d3db5911:c6fd485cc748f3b7", "illustration-content-design", "d994570d11483e12298c56f2626ec47c67bc366930eb5fb822ee13791d13c37a", "在此作品集工作区由 Illustration Designer 决定插画应呈现什么及元素关系，并直接形成用于图像生成的全彩提案契约；适用于新横幅、引导场景、紧凑物件、产品隐喻、叙事插画，或修正构图泛化、拼装感、语义不清和审美不足。"),
        entry("skill:project:project-03d84e40d3db5911:131c5b6b59fd5fe1", "image-prompt-guide", "a0a9ca68dc830b964a2107eefe8162994b1ba42fd4325eba75fefb66106b057a", "在此作品集工作区帮助 Visual Designer 或 Illustration Designer 把视觉分析、艺术指导、已批准参考或锁定风格转化为 Create Image 提示；特别适用于 Hero、项目封面、主视觉、平面插画和图像变体，并控制提示长度、视觉锚点、元素预算、延续风格、排除项和提示漂移。"),
        entry("skill:global:global-skills:75f33d2367bdb1fa", "image-vector-conversion", "1f9dfc263f01cf9470e7f9a2cf0e27c72ba9325608656e1bcc2e9d487df7ed54", "把明确批准的位图插画、图标或平面视觉转换为可编辑的 Adobe Illustrator 和 SVG 源文件，包含源锁定、路线选择、轮廓/填充分离或混合重构、语义图层和位图叠加保真 QA。仅在位图外观获批后使用，不用于图像生成、艺术指导、重设计或照片自动描摹。"),
        entry("skill:project:project-03d84e40d3db5911:c10bca8e0c46662c", "image-vector-conversion", "9c5e7098950b2d87638b7587cc1405075c2b6655b34be403c299bf55ef9da6bc", "作品集项目对全局标准流程的兼容入口：把明确批准的位图按路线选择、语义分层和保真 QA 转换为可编辑 AI 与 SVG 源文件。仅在位图获批后使用，不用于图像生成或重设计。"),
        entry("skill:project:project-03d84e40d3db5911:f3fdf927d6a0ec34", "implement-analyst", "a88a5d9d847cb8f913c5a0ab0f4c78aaad54dc17861020d4ebd31e09b7c35921", "在此作品集工作区检查参考网站、WebGL/Canvas 效果、滚动交互或 DOM/CSS/JS 模式时使用；在 Website Developer 开始前完成拆解、有边界的临时验证，并转化为可执行的开发简报。"),
        entry("skill:project:project-b22d22ea4c868e2f:8737e9d8fde3aa24", "implement-skin-runtime", "6ae9d2cb786734e9d3dcb783660d466feae2033b05229de8b811e96362cbe6c4", "在共享运行时与平台客户端实现已批准的 Codex 皮肤交接；供 Software Engineer 修改渲染器 CSS/JavaScript、CDP 传输、macOS Swift 或 Shell、Windows PowerShell、主题持久化、验证测试、素材同步、构建脚本、恢复或回滚，同时保留 Codex 原生行为。"),
        entry("skill:global:global-skills:073e334d0f6521b4", "information-architecture", "a5eb39dfe6c63a33ab1e5f84f5e6c9544f749edd09aa4ca84c0e259797398bfa", "在视觉设计开始前定义产品或网站的结构层，涵盖导航、内容层级、页面结构、URL 规则与用户流程；用于规划站点结构、定义导航、梳理流程和组织内容。"),
        entry("skill:global:global-skills:caae29468d7f1d96", "interface-concept-drafting", "e0bc8da201cfd85726ec5e3b665eea0787e38e0b4c14e20ba65f9563d3f59541", "当已批准的界面在实现前需要基于参考探索显著不同的视觉方向时，用 Create Image 创建并进行质量门控的 UI 概念草图。不得用于生产代码、精确文字或数据保真、可编辑 Figma 交付、图标批次或小型确定性 UI 修复。"),
        entry("skill:global:agent-skills:8a358c058705d465", "interview-designer", "36389fb30570d2d4fedba97ee25928d7552667f98e99d8a5bea6219c18096898", "以证据方法分析简历并设计面试策略，把“读简历后提问”转化为“定义标准、取证、模拟未来”；结合 Topgrading、绩效招聘和偏差控制，用于面试准备、结构化面试指南和验证候选人能力的问题设计。"),
        entry("skill:global:agent-skills:c6f4f6cad0da7e73", "json-canvas", "dd641d5335c6ba0067368d5fa72661a81a4a00d7abd83975288240affec848de", "创建和编辑 JSON Canvas（.canvas）文件中的节点、边、分组与连接；用于处理 .canvas、制作视觉画布、思维导图、流程图，或用户提到 Obsidian Canvas 时。"),
        entry("skill:project:project-03d84e40d3db5911:28da95aa18b79601", "json-canvas", "dd641d5335c6ba0067368d5fa72661a81a4a00d7abd83975288240affec848de", "创建和编辑 JSON Canvas（.canvas）文件中的节点、边、分组与连接；用于处理 .canvas、制作视觉画布、思维导图、流程图，或用户提到 Obsidian Canvas 时。"),
        entry("skill:project:project-03d84e40d3db5911:c5ec505f1301a952", "motion-designer", "f9240103e0de200abdaeeec19f65aa4684ca3ab3297de1d373f907073befb2f9", "在此作品集工作区需要重构动效参考、设计网页滚动动效、用 ProtoPie 构建已批准交互，或在 After Effects 中动画化并验证已批准视觉素材时使用；把工具中立的动效证据路由到 AE 或 ProtoPie 制作，同时保护工作副本、语义图层、矢量可编辑性、交互可逆性、预览 QA 和 Figma 播放交付。"),
        entry("skill:global:global-skills:91fb01dc3c7f0843", "motion-reference-reconstruction", "b666c2f9a9184b9eab446912a8a13b74600e744c2ee4829d68bfdadbf85f518e", "对照已批准静态设计分析 GIF、视频、录屏或交互参考，把可观察动效转化为有证据、工具中立的动效契约；在 AE、ProtoPie、Figma 或网页代码复刻参考前，用于测量图层运动、锚点、遮挡、时序、手势与排除项。不得用于静态 UI、简单转码、已批准动效实现或视觉重设计。"),
        entry("skill:project:project-03d84e40d3db5911:32b6e4d495d458be", "newpulse-illustration-style", "9fe0541918f995cf53efc574bc83beefd18f260fa1a8b43e67983c768ae17a52", "在此作品集工作区由 Illustration Designer 学习或应用 NewPulse 以填色为主的模块化插画语言，经过受控参考包、Create Image 风格探索、用户批准的位图锁定和忠实矢量转换。"),
        entry("skill:project:project-03d84e40d3db5911:c5e3e09fc83f53ba", "newpulse-ui-direction", "2d4b1ef537690f83d8245a21cb102ffd9ecfcf3b4f6e08b573caf05c45fcdb55", "在 NewPulse 产品 UI 重设计、视觉优化、扩展新屏、风格保真评审，或制定色彩、渐变、材质、图标、插画位置、组件与屏幕规则时使用；UX 获批后配合 UI Designer。不得用于专门插画制作、作品集包装、案例叙事、封面或网站视觉。"),
        entry("skill:global:agent-skills:9c80485595d9e698", "obsidian-ontology-sync", "cefd10cc6f3c2e0ab08dcb95bba680673c4922be1244c67e5f376e5d5f94f8ca", "在面向人的 Obsidian 笔记与机器可查询的结构化本体之间双向同步；自动从 Markdown 提取实体与关系、维护本体图，并反馈笔记结构改进，可通过 cron 每隔数小时同步。"),
        entry("skill:runtime:c5a84ad456d92a4f", "openai-api-troubleshooting", "3f3fc7fe54194b87813a9ea9e0542994885941a867ae559951b2d0c6841a442a", "当 OpenAI API 请求失败时分类可能原因、说明下一步并路由到正确后续；涵盖网络受阻、凭证无效、额度耗尽、速率限制以及模型、项目或组织权限问题。密钥配置交给 openai-platform-api-key，最新文档查询交给 openai-docs。"),
        entry("skill:runtime:8305ac37928fb98d", "openai-platform-api-key", "6e30162e19d1ce12cf156df84cdddd408b477384d414026a5d8f856e981f36a0", "当 Codex 构建、运行、测试、调试或配置由 OpenAI 或未指定提供商支持的 AI 应用、界面、脚本、CLI、生成器或工具时使用，尤其适用于仅说“使用 AI”或涉及 OPENAI_API_KEY、sk-proj 的请求。它是凭证门槛：安全检查，在 API 工作前询问复用还是新建，并绝不暴露明文。"),
        entry("skill:global:agent-skills:72aec36d76171f0e", "opencode-controller", "d9d702a82b7e8013733745e6ea3ca561e61d197f3ef9cd3bc2e0f82eae61f8ba", "通过斜杠命令控制和操作 Opencode，用于管理会话、选择模型、切换 plan/build Agent 并协调编码。"),
        entry("skill:project:project-03d84e40d3db5911:efc70fe4eecb9b16", "outline-illustration-draw", "a34690d47819cdbde8949d74d210ffdfaa3a9bcc5e56e6f35020b81e1c12053b", "通过参考分析、提示设计、图像生成、视觉 QA 和明确的用户批准门槛，创建并优化精致的描边 2D 或 2.5D 位图插画；用于空状态、编辑型产品插画、横幅、描边品牌素材或 Create Image 迭代。只交付获批位图，绝不执行 Illustrator Trace、SVG 转换或矢量重构。"),
