        CapabilityPurposeLocalizationEntry(
            resourceID: resourceID,
            kind: .skill,
            sourceName: sourceName,
            sourcePurposeSignature: sourcePurposeSignature,
            chinesePurpose: chinesePurpose
        )
    }
}
